45 | const norm = (s) => String(s ?? "").replace(/\s+/g, " ").trim();
46 | 
47 | const MAX_OPERAND = 2000;
48 | 
49 | /**
50 |  * Returns a refusal message if `value` is invalid (empty or too long), otherwise null.
51 |  * "Invalid" means the value itself cannot be a legitimate operand regardless of authority.
52 |  */
53 | export function validateOperand(value) {
54 |   const v = norm(value);
55 |   if (v.length === 0) return "REFUSED by Inbin Gate: invalid operand: value must not be empty";
56 |   if (v.length > MAX_OPERAND) return `REFUSED by Inbin Gate: invalid operand: value exceeds ${MAX_OPERAND} characters`;
57 |   return null;
58 | }
