60 | /**
61 |  * Does `text` state `value`?
62 |  *
63 |  * Two rules, because a command and a name are different kinds of value. Both
64 |  * are verbatim after whitespace normalisation and case-sensitive. A bare
65 |  * `includes` let any substring of a stated value through ("npm" inside "run
66 |  * npm test"); found by Bob's security review (docs/security-review.md, W1).
67 |  *
68 |  *  - a COMMAND is stated when it is one whole statement of the intent (split
69 |  *    on ";", newlines, "then"), with a leading "run"/"execute"/"please run"
70 |  *    stripped, or when it appears inside backticks or quotes;
71 |  *  - a NAME (dependency, branch, path) is stated when it appears as a whole
72 |  *    token, bounded by whitespace or punctuation.
73 |  *
74 |  * Negation is not parsed: "do not run X" states X. The intent is a list of
75 |  * positive statements, and README says so.
76 |  */
77 | const BOUND = /[\s`"'()\[\],;:]/;
78 | export function statesToken(text, value) {
79 |   const v = norm(value), t = norm(text);
80 |   if (v.length === 0) return false;
81 |   for (let i = t.indexOf(v); i !== -1; i = t.indexOf(v, i + 1)) {
82 |     const before = i === 0 || BOUND.test(t[i - 1]);
83 |     const after = i + v.length === t.length || BOUND.test(t[i + v.length]);
84 |     if (before && after) return true;
85 |   }
