106 | export function decide(action, args, sources, now = new Date()) {
107 |   const spec = OPERANDS[action];
108 |   if (!spec) return { allowed: false, action, reason: `unknown action ${action}`, operands: [] };
109 |   const results = [];
110 |   for (const [arg, predicate] of spec) {
111 |     const value = args?.[arg];
112 |     const invalid = validateOperand(value);
113 |     if (invalid) return { allowed: false, action, reason: invalid, operands: [] };
114 |     const v = norm(value);
115 |     const subject = `repo:${DOMAIN}`;
116 |     const store = emptyStore(CAPABILITIES, []);
117 |     const claims = [];
118 |     const stated = action === "run_command" ? statesCommand : statesToken;
119 |     if (sources.intent && stated(sources.intent.text, v)) {
120 |       mint(store, { subject, predicate, object: v }, { principalId: "principal:developer", channelId: "chan:developer-intent", trustDomain: DOMAIN }, now);
121 |       claims.push("developer intent");
122 |     }
123 |     if (policyStates(sources.policy, action, v)) {
124 |       mint(store, { subject, predicate, object: v }, { principalId: "principal:maintainer", channelId: "chan:repo-policy", trustDomain: DOMAIN }, now);
125 |       claims.push("repository policy");
126 |     }
127 |     // the agent's own proposal, always recorded, never governing
128 |     const own = mint(store, { subject, predicate, object: v }, { principalId: "principal:agent", channelId: "chan:agent-self", trustDomain: DOMAIN }, now);
129 |     const r = operative(store, subject, predicate, now);
130 |     const governs = r !== null && r.class !== "PROPOSING" && norm(r.value) === v;
131 |     const foundIn = (sources.untrusted || []).filter((u) => mentions(u.text, v)).map((u) => u.file);
132 |     results.push({
133 |       arg, predicate, value: v, allowed: governs,
134 |       class: r?.class ?? "PROPOSING",
135 |       establishedBy: claims,
136 |       foundInUntrusted: foundIn,
137 |       derivation: r?.derivation ?? own.authority?.derivation ?? [],
138 |       defeated: r?.defeatedCount ?? 0,
139 |     });
140 |   }
141 |   const allowed = results.every((x) => x.allowed);
142 |   const loser = results.find((x) => !x.allowed);
143 |   return {
144 |     allowed, action, operands: results,
145 |     reason: allowed
146 |       ? `every operand is established: ${results.map((x) => `${x.arg} by ${x.establishedBy.join(" and ")}`).join("; ")}`
147 |       : refusalText(action, loser),
148 |   };
