1 | #!/usr/bin/env node
2 | /**
3 |  * Inbin Gate as a Bob PreToolUse hook.
4 |  *
5 |  * Bob calls this before running one of its OWN tools (terminal, file writes)
6 |  * and passes the tool name and arguments on stdin. Exit 2 blocks the call and
7 |  * the reason on stderr is what Bob sees. So the gate governs Bob's native
8 |  * tools in every mode, with auto-approve on, and nothing has to be taken away
9 |  * from Bob. Registered in .bob/settings.json (project) under hooks.PreToolUse.
10 |  *
11 |  * Mapping of Bob tools to gate actions:
12 |  *   execute_command                       -> run_command  { cmd }
13 |  *   write_file | apply_diff |
14 |  *   search_and_replace | insert_content   -> edit_protected_file { path }, only when the
15 |  *                                            path matches the policy's protected patterns;
16 |  *                                            ordinary source edits pass untouched
17 |  *   anything else (reads, MCP tools)      -> allowed; our MCP tools gate themselves
18 |  */
19 | import { readFileSync } from "node:fs";
20 | import { relative, resolve, isAbsolute } from "node:path";
21 | import { gate, readPolicy, REPO } from "./core.mjs";
22 | 
23 | let payload = {};
24 | try { payload = JSON.parse(readFileSync(0, "utf8") || "{}"); } catch { process.exit(0); }
25 | const tool = payload.tool_name ?? payload.tool ?? "";
26 | const input = payload.tool_input ?? payload.input ?? {};
27 | 
28 | function refuse(reason) { process.stderr.write(reason + "\n"); process.exit(2); }
29 | 
30 | function protectedPath(p) {
31 |   if (!p) return false;
32 |   const rel = isAbsolute(p) ? relative(REPO, p) : p;
33 |   if (rel.startsWith("..")) return true; // outside the repository is always protected
34 |   const globs = readPolicy().protectedFiles || [];
35 |   return globs.some((g) => {
36 |     const re = new RegExp("^" + g.replace(/[.+^${}()|[\]\\]/g, "\\$&").replace(/\*\*\//g, "(.*/)?").replace(/\*\*/g, ".*").replace(/\*/g, "[^/]*") + "$");
37 |     return re.test(rel) || re.test(rel.split("/").pop());
38 |   });
39 | }
40 | 
41 | if (tool === "execute_command") {
42 |   const cmd = String(input.command ?? input.cmd ?? "");
43 |   const d = gate("run_command", { cmd });
44 |   if (!d.allowed) refuse(d.reason);
45 | } else if (["write_file", "write_to_file", "apply_diff", "search_and_replace", "insert_content", "edit_file"].includes(tool)) {
46 |   const p = String(input.path ?? input.file_path ?? "");
47 |   if (protectedPath(p)) {
48 |     const d = gate("edit_protected_file", { path: isAbsolute(p) ? relative(REPO, p) : p });
49 |     if (!d.allowed) refuse(d.reason);
50 |   }
51 | }
52 | process.exit(0);
